    "bank": "毛概",
    "type": "multiple",
    "question": "邓小平在总结历史经验教训的基础上，对社会主义社会的基本矛盾，特别是对社会主义初级阶段的主要矛盾进行了深入的思考，丰富发展了毛泽东的社会主义社会矛盾学说，直接为社会主义改革提供了理论基础。其主要内容有____",
